from rich.console import Console
from rich.traceback import install
import sys

class MockConsole(Console):
    def print(self, *args, **kwargs):
        raise RuntimeError("Print failed!")

def trigger_exception():
    1 / 0

if __name__ == "__main__":
    install(console=MockConsole())
    try:
        trigger_exception()
    except Exception:
        # This should trigger sys.excepthook
        pass
    # Actually, if I just let it crash, it should trigger sys.excepthook
    trigger_exception()

